module top_module(CLK, LOAD, IN, A_CLR, EN, Z, VAL);parameter N = 16;
input CLK, LOAD, A_CLR, EN;
input [N-1:0] IN;
output reg Z; 
output [N-1:0] VAL; 
reg [N-1:0] V;

always @(posedge CLK) begin
	if(LOAD)
		V <= IN;
	else if(EN)
		V <= (V ? V - 1'b1 : 1'b0);
end

always @(posedge A_CLR)
	V <= (A_CLR ? 16'd0 : V);


always@(V)
	Z <= (!V ? 1'b1 : 1'b0);

assign VAL = V;endmodule

