description:
Implement the Verilog module based on the following description.
We want to create a module that:

// (1) receives an 8-bit binary number,
// (2) checks if the number is odd,
// (3) counts the number of 1s in the binary number,
// (4) outputs a flag if the number is a multiple of 3,
// (5) provides a reset mechanism to reset all outputs.

// The input binary number is available on the input signal 'binary_num'. The output 'is_odd' should be set to 1 if the number is odd and 0 otherwise. The number of 1s in the binary number should be output on 'count_ones[3:0]'. The multiple of 3 flag should be set on 'is_multiple_of_three' if the number is a multiple of 3. The reset signal is active high synchronous.

module top_module(
    input wire clk,
    input wire reset,
    input wire [7:0] binary_num,
    output reg is_odd,
    output reg [3:0] count_ones,
    output reg is_multiple_of_three
);

code:
module top_module(
    input wire clk,
    input wire reset,
    input wire [7:0] binary_num,
    output reg is_odd,
    output reg [3:0] count_ones,
    output reg is_multiple_of_three
);

    integer i;

    always @(posedge clk) begin
        if (reset) begin
            is_odd <= 0;
            count_ones <= 0;
            is_multiple_of_three <= 0;
        end else begin
            // Check if odd
            is_odd <= binary_num[0];

            // Count number of 1s
            count_ones <= 0;
            for (i = 0; i < 8; i = i + 1) begin
                if (binary_num[i]) begin
                    count_ones <= count_ones + 1;
                end
            end

            // Check if multiple of 3
            is_multiple_of_three <= (binary_num % 3) == 0;
        end
    end

endmodule

