module alu_32bit(
    input      [31:0] a       ,
    input      [31:0] b       ,
    input      [2:0]  op      ,

    output reg [31:0] result
);

always @(*)
begin
    case (op)
        3'b000: result = a + b;
        3'b001: result = a - b;
        3'b010: result = a & b;
        3'b011: result = a | b;
        3'b100: result = a ^ b;
        default: result = 32'b0;
    endcase
end

endmodule

