description:
Implement the Verilog module based on the following description.
Build a 3-bit up/down counter with synchronous active high reset signal and control input for counting direction.
// (1) reset: Resets the counter to zero.
// (2) up: If high, count up; if low, count down.
// (3) q: The value of the counter.

module up_down_counter(
    input clk,
    input reset,
    input up,
    output reg [2:0] q);

code:
module up_down_counter(
    input clk,
    input reset,
    input up,
    output reg [2:0] q
);

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset: Reset the counter to zero
            q <= 3'b000;
        end else if (up) begin
            // Count up
            q <= q + 1;
        end else begin
            // Count down
            q <= q - 1;
        end
    end

endmodule

