description:
Design a sequence detector that identifies the binary sequence "1101" in a continuous input stream. When the reset signal is not active, the module transitions between five internal states based on the input `d_in`, which captures the incoming bits. The detection of the complete sequence will set the `found` output high when the state machine reaches state 4, indicating that the sequence "1101" has been detected.
module top_module(
  input rst_n, clock, d_in,
  output found
);

code:
module top_module(
  input rst_n, clock, d_in,
  output found
);reg [3:0] cstate;

  always @( posedge clock) begin
    if (!rst_n)
      cstate <= 0;
    else if (cstate == 0) begin
      if (d_in)
        cstate <= 1;
      else 
	cstate <= 0;
    end
    else if (cstate == 1) begin
      if (d_in)
        cstate <= 2;
      else 
	cstate <= 0;
    end
    else if (cstate == 2) begin
      if (d_in)
        cstate <= 2;
      else 
	cstate <= 3;
    end
    else if (cstate == 3) begin
      if (d_in)
        cstate <= 4;
      else 
	cstate <= 0;
    end
    else if (cstate == 4) begin
      if (d_in)
        cstate <= 2;
      else 
	cstate <= 0;
    end
    else cstate <= 0;
  end

  assign found = (cstate == 4);

endmodule

