module top_module(
  input clk,
  output reg [3:0] q
);reg [3:0] state;

  always @(posedge clk) begin
    if (state < 4'b1111) begin
      state <= state + 1;
    end else begin
      state <= 4'b0;
    end
  end

  assign q = state;

endmodule

